  try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var start=new CountDownLatch(1);var jobs=new ArrayList<Future<Map<String,Object>>>();for(int i=0;i<6;i++)jobs.add(pool.submit(()->{start.await();return mirror.record(owner,verified);}));start.countDown();var first=jobs.getFirst().get(10,TimeUnit.SECONDS);for(var job:jobs)assertEquals(first,job.get(10,TimeUnit.SECONDS));}
