  UUID bill=UUID.randomUUID();ledger.apply(actor,owner,UUID.randomUUID(),new JdbcMoneyLedger.Assess(0,2,bill,new MoneyLedger.Approval(completion,"a".repeat(64),Map.of(line,250000L))));var voucher=new MoneyLedger.Voucher("fresh-"+UUID.randomUUID(),LocalDate.of(2026,10,24),"OFFLINE_BANK",UUID.randomUUID(),"b".repeat(64));var original=new MoneyLedger.Payment(UUID.randomUUID(),bill,200000,voucher);ledger.apply(actor,owner,UUID.randomUUID(),new JdbcMoneyLedger.Collect(1,2,bill,original));
